package software.amazon.ion.impl.lite;

import java.io.Serializable;
import java.util.HashSet;
import java.util.Set;

public class IonField implements Serializable {
    private String name;
    private IonField parent;
    private Set<IonField> fields = new HashSet<>();

    public IonField() {}
    public IonField(String name, IonField parent) {
        this.name = name;
        this.parent = parent;
    }

    public boolean contains(String name) {
        for (IonField field : fields) {
            if (field.name.equals(name)) return true;
        }
        return false;
    }

    public IonField getField(String name) {
        for (IonField field : fields) {
            if (field.name.equals(name)) return field;
        }
        return null;
    }
    // Getters and Setters omitted for brevity
}

package software.amazon.ion.impl;

import software.amazon.ion.IonSystem;
import software.amazon.ion.IonType;
import software.amazon.ion.SystemSymbols;
import software.amazon.ion.impl.lite.IonField;

public class IonReaderBinaryUserXSelective extends IonReaderBinaryUserX {

    private IonField _current;
    private int hierarchy = 0;
    private int scalarLevel = Integer.MAX_VALUE;

    public IonReaderBinaryUserXSelective(byte[] data, int offset, int length,
                                         IonSystem system, IonField _current) {
        super(system, system.getCatalog(), UnifiedInputStreamX.makeStream(data, offset, length));
        this._current = _current;
    }

    @Override
    public IonType next() {
        IonType type = super.next();
        if (type == null) return null;

        String fieldName = getFieldName();
        if (fieldName == null || SystemSymbols.SYMBOLS.equals(fieldName) || scalarLevel != Integer.MAX_VALUE) {
            return type;
        }

        if (type == IonType.STRUCT || type == IonType.LIST) {
            IonField field = _current.getField(fieldName);
            if (field != null) {
                this._current = field;
                if (field.getFields().isEmpty()) {
                    scalarLevel = hierarchy;
                }
                return type;
            } else {
                // Byte-level skip: Step in and immediately out to advance parser offset past block
                super.stepIn();
                super.stepOut();
            }
            return next();
        } else {
            if (this._current.contains(fieldName)) {
                return type;
            } else {
                return next();
            }
        }
    }

    @Override
    public void stepIn() {
        hierarchy = (hierarchy << 1);
        if (getFieldName() != null && !SystemSymbols.SYMBOLS.equals(getFieldName())) {
            hierarchy = hierarchy + 1;
        }
        super.stepIn();
    }

    @Override
    public void stepOut() {
        if ((hierarchy & 1) == 1 && scalarLevel == Integer.MAX_VALUE) {
            this._current = this._current.getParent();
        }
        hierarchy = hierarchy >> 1;
        if (scalarLevel != Integer.MAX_VALUE && scalarLevel == hierarchy) {
            this._current = this._current.getParent();
            scalarLevel = Integer.MAX_VALUE;
        }
        super.stepOut();
    }
}

