private void setupSelection(ProceedingJoinPoint point) {
    Object body = point.getArgs()[1];
    if (body instanceof RestRequestBody) {
        IonField root = ((RestRequestBody<?>) body).getSelection();
        setParent(root, root.getFields());
    }
}

private void setParent(IonField parent, Set<IonField> children) {
    for (IonField child : children) {
        child.setParent(parent);
        if (!child.getFields().isEmpty()) {
            setParent(child, child.getFields());
        }
    }
}

public class ScalarSelectionQueryResultLoader implements QueryResultLoader {
    private final AdvancedCache<?, ?> cache;
    private final IonSystem ionSystem = IonSystemBuilder.standard().build();
    private final IonField fields;

    @Override
    public Object load(EntityInfo entityInfo) {
        try {
            // Fetch raw binary Amazon Ion bytes directly from cache store
            byte[] ionData = (byte[]) cache.withEncoding(IonEncoder.class).get(decodeKey(entityInfo));

            // Selective reader skips unselected fields at byte level
            IonReader ionReader = new IonReaderBinaryUserXSelective(
                    ionData, 5, ionData.length - 5,
                    ionSystem, fields
            );
            StringBuilder builder = new StringBuilder();
            IonWriter ionWriter = IonTextWriterBuilder.json().build(builder);

            // Pipe directly to output JSON without POJO object instantiation
            ionWriter.writeValues(ionReader);
            return builder.toString();
        } catch (IOException e) {
            throw new RuntimeException(e);
        }
    }
}
